/**
 * Platform independent version of asctime_r: convert a `struct tm` into a null-terminated string.
 * @tparam N The size of \p buf; must be at least 26 characters.
 * @param tm The time component representation.
 * @param buf The character buffer to render the string into. Must be at least 26 characters.
 * @returns \p buf, or `nullptr` if an error occurs.
 */
template <size_t N>
inline char* asctime_r(const struct tm* tm, char (&buf)[N]) noexcept
{
    // Buffer requirements as specified:
    // https://linux.die.net/man/3/gmtime_r
    // https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/asctime-s-wasctime-s?view=msvc-170
    static_assert(N >= 26, "Insufficient buffer size");
#if CARB_PLATFORM_WINDOWS
    return asctime_s(buf, N, tm) == 0 ? buf : nullptr;
#elif CARB_POSIX
    return ::asctime_r(tm, buf);
#else
    CARB_UNSUPPORTED_PLATFORM();
#endif
}

/**
 * Platform independent version of ctime_r; convert a `time_t` into a null-terminated string in the user's local time
 * zone.
 *
 * Equivalent to:
 * ```
 * struct tm tmBuf;
 * return asctime_r(localtime_r(timep, &tmBuf), buf);
 * ```
 * @tparam N The size of \p buf; must be at least 26 characters.
 * @param timep A pointer to a `time_t`.
 * @param buf The character buffer to render the string into. Must be at least 26 characters.
 * @returns \p buf, or `nullptr` if an error occurs.
 */
template <size_t N>
inline char* ctime_r(const time_t* timep, char (&buf)[N]) noexcept
{
    // Buffer requirements as specified:
    // https://linux.die.net/man/3/gmtime_r
    // https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/ctime-s-ctime32-s-ctime64-s-wctime-s-wctime32-s-wctime64-s?view=msvc-170
    static_assert(N >= 26, "Insufficient buffer size");
#if CARB_PLATFORM_WINDOWS
    auto err = ctime_s(buf, N, timep);
    return err == 0 ? buf : nullptr;
#elif CARB_POSIX
    return ::ctime_r(timep, buf);
#else
    CARB_UNSUPPORTED_PLATFORM();
#endif
}

/**
 * Platform independent version of gmtime_r: convert a `time_t` to UTC component representation.
 * @param timep A pointer to a `time_t`.
 * @param result A pointer to a `struct tm` that will receive the result.
 * @returns \p result if conversion succeeded; `nullptr` if the year does not fit into an integer or an error occurs.
 */
inline struct tm* gmtime_r(const time_t* timep, struct tm* result) noexcept
{
#if CARB_PLATFORM_WINDOWS
    auto err = ::gmtime_s(result, timep);
    return err == 0 ? result : nullptr;
#elif CARB_POSIX
    return ::gmtime_r(timep, result);
#else
    CARB_UNSUPPORTED_PLATFORM();
#endif
}

/**
 * Platform independent version of localtime_r: convert a `time_t` to local timezone component representation.
 * @param timep A pointer to a `time_t`.
 * @param result A pointer to a `struct tm` that will receive the result.
 * @returns \p result if conversion succeeded; `nullptr` if the year does not fit into an integer or an error occurs.
 */
inline struct tm* localtime_r(const time_t* timep, struct tm* result) noexcept
{
#if CARB_PLATFORM_WINDOWS
    auto err = ::localtime_s(result, timep);
    return err == 0 ? result : nullptr;
#elif CARB_POSIX
    return ::localtime_r(timep, result);
#else
    CARB_UNSUPPORTED_PLATFORM();
#endif
}

/** Retrieves the current steady (monotonic) clock timestamp in nanoseconds.
 *
 *  @returns The elapsed time in nanoseconds since an arbitrary epoch (usually system boot).
 *           This will always be coming from the monotonic steady clock and will not be subject
 *           to NTP wallclock updates.  Some platforms may however slightly adjust this clock
 *           by slowing it down or speeding it up as wall clock time updates arrive.  It will
 *           still be guaranteed to be monotonically increasing however.
 *
 *  @note The values returned here may not include time while the system is suspended or
 *        hibernating.  This behaviour is platform dependent however.
 */
inline std::chrono::nanoseconds getSteadyTimestampNs()
{
    return std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now().time_since_epoch());
}

/** Retrieves the current wallclock time in nanoseconds since the Unix epoch.
 *
 *  @returns The current wallclock system time in nanosecnds.  This will always be relative
 *           to the Unix epoch (midnight January 1, 1970).  The values returned here will be
 *           subject to NTP wallclock updates.  This could result in a newer timestamp
 *           returning a smaller value than a previous one.  The clock corrections are
 *           typically small (on the order of hundreds of milliseconds), but could be large
 *           on occasion.  If this is problematic, it is the caller's responsibility to
 *           detect and handle such time jumps by comparing to a previous result.
 */
inline std::chrono::nanoseconds getNanosecondsSinceUnixEpoch()
{
#if CARB_PLATFORM_WINDOWS
    CARBWIN_FILETIME ft;

    GetSystemTimeAsFileTime(reinterpret_cast<FILETIME*>(&ft));

    // Convert to 100ns units (ie: 'NT ticks').
    uint64_t windowsTime = (((uint64_t)ft.dwHighDateTime << 32) | ft.dwLowDateTime);

    // Convert Windows epoch (1601-01-01) to Unix epoch (1970-01-01).
    // Windows epoch is 116444736000000000 100ns units before Unix epoch.
    constexpr uint64_t kWindowsToUnixEpoch = 116444736000000000ULL;

    // Convert to Unix epoch and then to nanoseconds.
    return std::chrono::nanoseconds((windowsTime - kWindowsToUnixEpoch) * 100);
#elif CARB_POSIX
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    return std::chrono::nanoseconds(((int64_t)ts.tv_sec * 1'000'000'000ll) + ts.tv_nsec);
#else
    CARB_UNSUPPORTED_PLATFORM();
#endif
}

/** Calculates the approximate monotonic time in nanoseconds since the Unix epoch.
 *
 *  @param[in] absTimestampNs       The absolute timestamp in nanoseconds since the Unix epoch
 *                                  to be used to calculate the absolute timestamp of the
 *                                  arbitrary epoch used for the steady clock.  This value will
 *                                  only be consumed on the first call so that a consistent epoch
 *                                  is used for all calculations.
 *  @param[in] steadyTimestampNs    The current monotonic/steady timestamp in nanoseconds since
 *                                  an arbitrary but consistent epoch (usually system boot time).
 *                                  This can be the value returned from getSteadyTimestampNs().
 *                                  The source of this value should be consistent for all calls.
 *                                  This value may be 0 to use getSteadyTimestampNs() instead to
 *                                  get the monotonic timestamp.  Defaults to 0.
 *
 *  @returns The calculated absolute monotonic timestamp in nanoseconds.  This will always be
 *           relative to the Unix epoch (midnight January 1, 1970) but is not guaranteed to be
 *           accurate since it would not be subject to wall clock time corrections  All the
 *           returned timestamps will be monotonically increasing, but will likely drift
 *           especially over very long sessions.
 *
 *  @note If the system wall clock time is incorrect on the first call, the results from this
 *        function will continue to be incorrect for the remainder of the process.  All of the
 *        returned times will still be somewhat accurate relative to the steady clock epoch
 *        (usually system boot time).
 *
 *  @note All clocks drift.  The system wall clock time is periodically corrected through NTP
 *        updates because of this.  However, the monotonic clocks do not get such updates and
 *        any drift that occurs in them will be permanent for the session and accumulate in
 *        timing results.
 */
inline std::chrono::nanoseconds getMonotonicNanosecondsSinceUnixEpoch(
    std::chrono::nanoseconds absTimestampNs, std::chrono::nanoseconds steadyTimestampNs = std::chrono::nanoseconds(0))
{
    std::chrono::nanoseconds now = steadyTimestampNs.count() == 0 ? getSteadyTimestampNs() : steadyTimestampNs;
    static std::chrono::nanoseconds nsFromUnixEpochToBoot = absTimestampNs - now;

    return now + nsFromUnixEpochToBoot;
}

/** Retrieves the approximate monotonic time in nanoseconds since the Unix epoch.
 *
 *  @returns The approximate current time in nanoseconds.  This will always be relative to the
 *           Unix epoch (midnight January 1, 1970) but is not guaranteed to be accurate since
 *           it would not be subject to wall clock time corrections.  All the returned timestamps
 *           will be monotonically increasing, but will likely drift especially over very long
 *           sessions.
 *
 *  @note If the system wall clock time is incorrect on the first call, the results from this
 *        function will continue to be incorrect for the remainder of the process.  All of the
 *        returned times will still be somewhat accurate relative to the steady clock epoch
 *        (usually system boot time).
 *
 *  @note All clocks drift.  The system wall clock time is periodically corrected through NTP
 *        updates because of this.  However, the monotonic clocks do not get such updates and
 *        any drift that occurs in them will be permanent for the session and accumulate in
 *        timing results.
 */
inline std::chrono::nanoseconds getMonotonicNanosecondsSinceUnixEpoch()
{
    static std::chrono::nanoseconds nsSinceEpoch = getNanosecondsSinceUnixEpoch();

    return getMonotonicNanosecondsSinceUnixEpoch(nsSinceEpoch);
}

